package main

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"
)

// formatSize formats bytes according to flags
func formatSize(bytes int64, useSI, noPrefix, showInKiB bool) string {
	if noPrefix {
		return fmt.Sprintf("%d", bytes)
	}
	if showInKiB {
		if useSI {
			// kB
			v := float64(bytes) / 1000.0
			return fmt.Sprintf("%.1f kB", v)
		}
		v := float64(bytes) / 1024.0
		return fmt.Sprintf("%.1f KiB", v)
	}
	if useSI {
		if bytes < 1000 {
			return fmt.Sprintf("%d B", bytes)
		}
		units := []string{"kB", "MB", "GB", "TB", "PB", "EB"}
		v := float64(bytes)
		idx := -1
		for v >= 1000 && idx < len(units)-1 {
			v /= 1000
			idx++
		}
		return fmt.Sprintf("%.1f %s", v, units[idx])
	}
	// binary
	if bytes < 1024 {
		return fmt.Sprintf("%d B", bytes)
	}
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	v := float64(bytes)
	idx := -1
	for v >= 1024 && idx < len(units)-1 {
		v /= 1024
		idx++
	}
	return fmt.Sprintf("%.1f %s", v, units[idx])
}

// natural sort helpers
type naturalChunk struct {
	isNum bool
	str   string
	num   int64 // numeric value if isNum (may overflow? use int64, but for large numbers > int64? Use string compare fallback)
	numStr string
	hasLeadingZero bool
}

func splitNatural(s string) []naturalChunk {
	var chunks []naturalChunk
	i := 0
	n := len(s)
	for i < n {
		if s[i] >= '0' && s[i] <= '9' {
			j := i
			for j < n && s[j] >= '0' && s[j] <= '9' {
				j++
			}
