func absPath(p string) string {
	if p == "" {
		return ""
	}
	abs, err := filepath.Abs(p)
	if err != nil {
		return filepath.Clean(p)
	}
	return filepath.Clean(abs)
}

func buildScanConfig(ignoreDirs []string, ignorePatterns []string, ignoreFrom string, noHidden, noCross, followSymlinks, showAnnexed bool, typeFilters, excludeFilters []string, sinceStr, untilStr, maxAgeStr, minAgeStr string, rootPath string) (*ScanConfig, error) {
	cfg := &ScanConfig{
