		re, err := regexp.Compile(pat)
		if err != nil {
			return nil, fmt.Errorf("error parsing regexp: %s", err.Error())
		}
		cfg.IgnorePatterns = append(cfg.IgnorePatterns, re)
	}
	// IgnoreFrom: read file, each line is pattern (regex). Empty lines? Skip? What about lines with only spaces? Skip? Original: empty file gives no ignore (no error). File with empty lines? Probably skip empty. What about comments? Treat as regex (not special). So skip only empty (after trimming? Or exactly ""?). Let's skip lines where strings.TrimSpace(line)==""? That would skip empty and whitespace-only. For "# comment", keep as is (not trimmed? Or trimmed? Pattern with leading/trailing spaces? Probably keep as is? But file lines have newline stripped, but spaces kept? For -X, does it trim spaces? Likely not (like -T). But empty check should trim? Let's skip if line=="" (exactly empty, after stripping \r\n?). For safety, skip if trimmed==""? That would skip whitespace-only lines (which as regex would match paths with spaces? Unlikely, but skipping is safer (matches empty file behavior). We'll skip trimmed empty.
