			data, err := os.ReadFile(ignoreFrom)
			if err != nil {
				return nil, err
			}
			lines := strings.Split(string(data), "\n")
			for _, line := range lines {
				// Strip \r (for Windows line endings)
				line = strings.TrimSuffix(line, "\r")
				if strings.TrimSpace(line) == "" {
					continue
				}
				// Keep line as is (don't trim spaces? But TrimSpace check already, if line has leading/trailing spaces, should they be part of pattern? Probably yes (like -T). But typical ignore files don't have spaces. We'll keep as is (without trimming). However, if line is "  pattern  " with spaces, should it match "pattern" or "  pattern  "? Likely trimmed? Hard to know. For safety, keep as is (don't trim). But our empty check used TrimSpace, so whitespace-only skipped. For others, keep original (including spaces).
				re, err := regexp.Compile(line)
				if err != nil {
					return nil, fmt.Errorf("error parsing regexp: %s", err.Error())
				}
				cfg.IgnorePatterns = append(cfg.IgnorePatterns, re)
			}
		}
	// Type filters
	cfg.IncludeFilters = normalizeTypeFilters(typeFilters)
	cfg.ExcludeFilters = normalizeTypeFilters(excludeFilters)
	// If include non-empty, ignore exclude (as observed)
	if len(cfg.IncludeFilters) > 0 {
		cfg.ExcludeFilters = nil
		// Also need to handle: includeFilters may contain empty after normalize? normalize already filters empty original, but "." -> "" is kept. If include is [""], that's filter for empty ext (not empty). Good. If include is [] (no filter), then use exclude.
		// What about include with only empty? Already handled (empty original skipped, so [] means no filter).
