		}
		cfg.UntilTime = &t
		cfg.UntilIsDateOnly = isDateOnly
	}
	if maxAgeStr != "" {
		secs, err := parseDuration(maxAgeStr)
		if err != nil {
			return nil, fmt.Errorf("invalid time filter: invalid --max-age value: %s", err.Error())
		}
