	showVersion, _ := cmd.Flags().GetBool("version")
	if showVersion {
		fmt.Fprintf(cmd.OutOrStdout(), "Version:\t %s\nBuilt time:\t %s\nBuilt user:\t %s\n", versionBuilt, builtTime, builtUser)
		return nil
	}
	if len(args) > 1 {
		return fmt.Errorf("accepts at most 1 arg(s), received %d", len(args))
	}
	return runApp(cmd, args)
}

