package main

import (
	"fmt"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/gdamore/tcell/v2"
)

type tuiState struct {
	root         *Item
	current      *Item
	currentPath  string
	isDisks      bool
	disks        []DiskInfo
	diskCursor   int
	cursor       int
	offset       int
	sortBy       string // size, name, itemCount, mtime
	sortOrder    string // asc, desc
	showApparent bool
	showCount    bool
	showMtime    bool
	useMax       bool // B toggle: bars relative to max (true) vs total (false)
	noUnicode    bool
	screen       tcell.Screen
	cfg          Config
	scanAbs      string
	showHelp     bool
	quitPath     string
	shouldQuit   bool
	quitPrint    bool
}

func runInteractiveTUI(root *Item, cfg Config, scanAbs string, showDisks bool) error {
	s, err := tcell.NewScreen()
	if err != nil {
		return fmt.Errorf("error creating screen: %s", err.Error())
	}
	if err := s.Init(); err != nil {
		return fmt.Errorf("error creating screen: %s", err.Error())
	}
	defer s.Fini()
	if cfg.Mouse {
		s.EnableMouse()
	} else {
		s.DisableMouse()
	}
	s.EnablePaste()
	s.Clear()

	st := &tuiState{
		root:         root,
		current:      root,
		currentPath:  scanAbs,
		isDisks:      showDisks,
		cursor:       0,
		offset:       0,
		sortBy:       "size",
		sortOrder:    "desc",
		showApparent: cfg.ShowApparentSize,
		showCount:    cfg.ShowItemCount,
		showMtime:    cfg.ShowMTime,
		useMax:       false,
		noUnicode:    cfg.NoUnicode,
		screen:       s,
		cfg:          cfg,
		scanAbs:      scanAbs,
	}
	// Handle config sorting
	if cfg.Sorting.By != "" {
		b := cfg.Sorting.By
		// Map: size, name, itemCount, mtime (also support count? mtime? etc.)
		if b == "size" || b == "name" || b == "itemCount" || b == "mtime" {
			st.sortBy = b
		} else if b == "count" {
			st.sortBy = "itemCount"
		}
	}
	if cfg.Sorting.Order != "" {
		o := cfg.Sorting.Order
		if o == "asc" || o == "desc" {
			st.sortOrder = o
		}
	}
	if showDisks {
		disks, err := getDisks()
		if err != nil {
			return err
		}
		st.disks = disks
		st.currentPath = ""
	} else {
		// Precompute item counts and mtimes for display/sorting
		computeCounts(root)
	}

	for {
		drawTUI(st)
		ev := s.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventResize:
			s.Sync()
		case *tcell.EventKey:
			if st.showHelp {
				st.showHelp = false
				continue
			}
			if handleKey(st, ev) {
				// quit
				if st.quitPrint {
					// Print current path to stdout after Fini (deferred Fini will restore terminal, then print)
					// Need to Fini first, then print? Defer will Fini after return, but we need to print after Fini. So Fini now, print, then return.
					s.Fini()
					fmt.Println(st.quitPath)
					return nil
				}
				return nil
			}
		case *tcell.EventMouse:
			// Ignore mouse for now (even if enabled, no handling)
			_ = ev
		}
		if st.shouldQuit {
			if st.quitPrint {
				s.Fini()
				fmt.Println(st.quitPath)
				return nil
			}
			return nil
		}
	}
}

func computeCounts(item *Item) {
	if !item.IsDir {
		return
	}
	for _, ch := range item.Children {
		if ch.IsDir {
			computeCounts(ch)
		}
	}
}

func getItemCount(item *Item) int {
	if !item.IsDir {
		return 1
	}
	count := 0
	var dfs func(*Item)
	dfs = func(it *Item) {
		for _, ch := range it.Children {
			count++
			if ch.IsDir {
				dfs(ch)
			}
		}
	}
	dfs(item)
	return count
}

func getMtime(item *Item) time.Time {
	if !item.IsDir {
		return item.MTimeFull
	}
	max := item.MTimeFull
	var dfs func(*Item)
	dfs = func(it *Item) {
		for _, ch := range it.Children {
			if ch.MTimeFull.After(max) {
				max = ch.MTimeFull
			}
			if ch.IsDir {
				dfs(ch)
			}
		}
	}
	dfs(item)
	// Also consider dir's own mtime? Already max initialized to item's own. Good.
	return max
}

