					st.sortOrder = "desc"
				} else {
					st.sortOrder = "asc"
				}
			} else {
				st.sortBy = "mtime"
				st.sortOrder = "asc"
			}
			st.cursor = 0
			st.offset = 0
			st.diskCursor = 0
			return false
		case 'c':
			st.showCount = !st.showCount
			return false
		case 'm':
			st.showMtime = !st.showMtime
			return false
		case 'a':
			st.showApparent = !st.showApparent
			return false
		case 'B':
			st.useMax = !st.useMax
			return false
		case 'r':
			// Rescan current directory (re-scan from filesystem? For imported/DB? Rescan from filesystem? Probably re-scan current path from filesystem (ignoring DB/input?).
			// For minimal, no-op (just redraw). To implement rescan, need to re-scan currentPath from filesystem with same scan config (filters, etc.). That's complex (need scan config). For now, no-op.
			return false
