			return false
		case 'b':
			// Spawn shell - if NoSpawnShell, ignore. Else suspend TUI, spawn shell, resume? Complex (need to suspend screen, exec shell, resume). For minimal, no-op.
			return false
		case 'd', 'e', ' ', 'I', 'v', 'o', 'i', 'E':
			// Item actions - no-ops for minimal
			return false
		}
		return false
	}
	// Handle special keys
	switch key {
	case tcell.KeyUp:
		moveCursor(st, -1)
	case tcell.KeyDown:
		moveCursor(st, 1)
	case tcell.KeyPgUp:
		moveCursor(st, -10)
	case tcell.KeyPgDn:
		moveCursor(st, 10)
	case tcell.KeyHome:
		moveTop(st)
	case tcell.KeyEnd:
		moveBottom(st)
	case tcell.KeyEnter, tcell.KeyRight:
		goInto(st)
	case tcell.KeyLeft:
		goParent(st)
	case tcell.KeyEsc:
		if st.showHelp {
			st.showHelp = false
		}
	}
	return false
}

